import { createLazyExport } from '../shared/lazyExport'

// The SBF See Navigationsaufgaben (ADR-0068): generated by backend/scripts/export_sbf_navigation.py
// into src/sbf/data/sbf_navigation.gen.json from the reviewed YAML. Only an SBF build with VITE_SBF=on
// carries them: the import below sits behind the build's literal flag, so with "off" the bundler drops
// it and no chunk with the tasks is written (scripts/check-sbf-build.mjs checks that).

export interface NavigationImage {
  src: string
  width: number
  height: number
}

export interface NavigationSubtask {
  number: number
  text: string
  result: string
  // SKS Lotse's own tolerance, not official (usual exam practice); null where no number applies.
  own_tolerance: string | null
  // The subtask as the PDF prints it: its table row, and apart its result (shown once answered).
  original: { question: NavigationImage; result: NavigationImage } | null
}

export interface NavigationTask {
  number: number
  situation: string[]
  subtasks: NavigationSubtask[]
  footnotes: string[]
}

export interface NavigationExport {
  source: string
  chart_notice: string
  sections_notice: string
  chart_sections: { number: number; corners: string[] }[]
  pool_notice: string
  pool: { number: number; text: string }[]
  aids: string[]
  pass_points: number
  scoring: string[]
  typo_fixes: { task: number; subtask: number; field: 'text' | 'result'; official: string; corrected: string }[]
  tasks: NavigationTask[]
}

// Where the build puts the originals (vite.config.ts copies them only with VITE_SBF=on).
export const ORIGINALS_PATH = '/navigation/originals/'

export function navigationTask(data: NavigationExport, number: number): NavigationTask | null {
  return data.tasks.find((task) => task.number === number) ?? null
}

// One point per subtask (SpFV Anlage 3 Nr. 1.1).
export function taskMaxPoints(task: NavigationTask): number {
  return task.subtasks.length
}

// A typo the operator corrected in this subtask's field, with the official text (ADR-0068).
export function typoFix(data: NavigationExport, task: number, subtask: number, field: 'text' | 'result') {
  return data.typo_fixes.find((fix) => fix.task === task && fix.subtask === subtask && fix.field === field) ?? null
}

export const navigationSource = createLazyExport(
  () =>
    import.meta.env.VITE_SBF === 'on'
      ? import('./data/sbf_navigation.gen.json').then((module) => module.default as unknown as NavigationExport)
      : Promise.reject(new Error('Die Navigationsaufgaben sind in diesem Build nicht enthalten.')),
  (data: NavigationExport) => data,
)
